def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    sigmoid_penalty = 1.0 / (1.0 + np.exp(remaining))
    balance_term = -np.abs(remaining - 0.5)
    return np.where(remaining < 0, -np.inf, -sigmoid_penalty + balance_term)

