def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, -1.0 / (remaining + 0.1) - (remaining - 0.5) ** 2)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_slack = 0.1 * bins
    score = -np.exp(np.abs(remaining - target_slack) / (bins + 1e-8))
    return np.where(remaining < 0, -np.inf, score)
